head.script:
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.checkValue = function(id, value) {
    if (WebSquare.wUnit.getDomById($p.id + id).innerText == value) {
        return true;
    }
    return false
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 그리드뷰 컬럼의 속성값을 inputType=select, sortLabel=true로 설정하고 샘플파일(default = true)의 col1항목 헤더를 더블클릭하여 오름차순으로 sorting한다.
    //1. Set the attribute values of the grid view column to inputType = select, sortLabel = true, and double-click the col1 item header of the sample file (default = true) to sort in ascending order.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').setAttribute('sortlabel', 'true')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_1').setAttribute('inputtype', 'select')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_1').setAttribute('sortlabel', 'true')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_1').setAttribute('inputtype', 'select')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_2_1').setAttribute('sortlabel', 'true')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_2_1').setAttribute('inputtype', 'select')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_3_1').setAttribute('sortlabel', 'true')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_3_1').setAttribute('inputtype', 'select')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column15')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. The sorting result of col1 is shown as 01, 02, 03, 04.
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_0_1', '01')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_1_1', '02')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_2_1', '03')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkValue($p.id+'gridView1_cell_3_1', '04')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
